// Superposition visual properties
export interface SuperpositionEffect {
  readonly blurStdDev:     number;  // Gaussian blur — default 2
  readonly ghostOffset:    number;  // px — default 10
  readonly opacityMin:     number;  // 0.3
  readonly opacityMax:     number;  // 0.7
}

export const SUPERPOSITION_DEFAULTS: SuperpositionEffect = Object.freeze({
  blurStdDev:  2,
  ghostOffset: 10,
  opacityMin:  0.3,
  opacityMax:  0.7,
});

export function canSuperpose(state: string): boolean {
  return state === "actif" || state === "instable";
}

