#[derive(Debug, Clone)]
pub struct SuperpositionEffect {
    pub blur_std_dev:  f64,   // Gaussian blur
    pub ghost_offset:  f64,   // px
    pub opacity_min:   f64,
    pub opacity_max:   f64,
}

impl Default for SuperpositionEffect {
    fn default() -> Self {
        Self { blur_std_dev: 2.0, ghost_offset: 10.0, opacity_min: 0.3, opacity_max: 0.7 }
    }
}

/// CanSuperpose — capacité déclarée
pub fn can_superpose(nucleus_state: &str) -> bool {
    matches!(nucleus_state, "actif" | "instable")
}
